import{_ as a,c as e,o as i,b0 as n}from"./chunks/framework.C5ev1SXp.js";const u=JSON.parse('{"title":"LV040-WiFi连接与ping探测","description":null,"frontmatter":{"title":"LV040-WiFi连接与ping探测","date":"2026-10-30T22:29:14.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/advanced-chapter/esp8266/126d63825c420b95847c6ac7","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-30T22:29:14.185Z","fulluuid":"5847c6ac7f5a48bc9d6df9fea60d038d","useduuid":"5847c6ac"}},"headers":[],"relativePath":"sdoc/advanced-chapter/esp8266/126d63825c420b95847c6ac7.md","filePath":"sdoc/30-进阶篇/02-ESP8266/LV040-WiFi连接与ping探测.md","lastUpdated":1793371011000}'),t={name:"sdoc/advanced-chapter/esp8266/126d63825c420b95847c6ac7.md"};function p(d,s,l,o,c,r){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="lv040-wifi连接与ping探测" tabindex="-1">LV040-WiFi连接与ping探测 <a class="header-anchor" href="#lv040-wifi连接与ping探测" aria-label="Permalink to &quot;LV040-WiFi连接与ping探测&quot;">​</a></h1><p>本文基于 <code>atk-f103</code> 仓库 <code>flash-app</code> 工程的 ATK-MW8266D 驱动，记录 WiFi 联网的完整链路：先用 AT 指令把连接、断开、信息查询、ping 探测逐个跑通，再封装成串口命令，最后复盘一次 ping 不通的排查过程。</p><p>涉及源码（均在 <code>flash-app</code> 工程内，下文不再重复标注）：</p><ul><li><code>Drivers/BSP/ATK_MW8266D/atk_mw8266d.c/.h</code>：业务层，收发与解析 AT 应答</li><li><code>Drivers/BSP/ATK_MW8266D/atk_mw8266d_test.c/.h</code>：串口命令实现</li><li><code>Core/Src/main.c</code>：命令注册</li></ul><h2 id="一、-at-指令联网" tabindex="-1">一、 AT 指令联网 <a class="header-anchor" href="#一、-at-指令联网" aria-label="Permalink to &quot;一、 AT 指令联网&quot;">​</a></h2><h3 id="_1-工作模式切换-at-cwmode" tabindex="-1">1. 工作模式切换（AT+CWMODE） <a class="header-anchor" href="#_1-工作模式切换-at-cwmode" aria-label="Permalink to &quot;1. 工作模式切换（AT+CWMODE）&quot;">​</a></h3><p>ESP8266 有三种工作模式：1 为 STA（连别人），2 为 AP（被连），3 为 STA + AP 共存。联网上网只用 STA，因此连接前先确保处于模式 1：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AT+CWMODE=1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>目标模式与当前模式相同时，模块回 <code>no change</code>，同样带 <code>OK</code>，无需特判。模式切换后射频要重新初始化，建议延时 200 ms 再做后续操作。</p><h3 id="_2-连接与断开热点-at-cwjap-at-cwqap" tabindex="-1">2. 连接与断开热点（AT+CWJAP / AT+CWQAP） <a class="header-anchor" href="#_2-连接与断开热点-at-cwjap-at-cwqap" aria-label="Permalink to &quot;2. 连接与断开热点（AT+CWJAP / AT+CWQAP）&quot;">​</a></h3><p>连接热点：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AT+CWJAP=&quot;MyWiFi&quot;,&quot;12345678&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>连接成功是一个漫长的应答流：<code>WIFI CONNECTED</code>、<code>WIFI GOT IP</code>，最后才给 <code>OK</code>，整个过程通常 1～5 s。失败时模块回 <code>+CWJAP:&lt;错误码&gt;</code> 加 <code>FAIL</code>，<strong>没有 OK</strong>——这一点对超时策略很关键，详见本文第三节。</p><p>开放热点不传密码即可：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AT+CWJAP=&quot;MyOpenWiFi&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>断开热点：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AT+CWQAP</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>断开只脱网，模式不变，IP 随即回落到 <code>0.0.0.0</code>。</p><h3 id="_3-查询网络信息" tabindex="-1">3. 查询网络信息 <a class="header-anchor" href="#_3-查询网络信息" aria-label="Permalink to &quot;3. 查询网络信息&quot;">​</a></h3><h4 id="_3-1-本机-ip-与-mac-at-cifsr-at-cipstamac" tabindex="-1">3.1 本机 IP 与 MAC（AT+CIFSR / AT+CIPSTAMAC?） <a class="header-anchor" href="#_3-1-本机-ip-与-mac-at-cifsr-at-cipstamac" aria-label="Permalink to &quot;3.1 本机 IP 与 MAC（AT+CIFSR / AT+CIPSTAMAC?）&quot;">​</a></h4><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AT+CIFSR</span></span>
<span class="line"><span>+CIFSR:STAIP,&quot;192.168.10.101&quot;</span></span>
<span class="line"><span>+CIFSR:STAMAC,&quot;dc:4f:22:xx:xx:be&quot;</span></span>
<span class="line"><span>OK</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>未联网时 <code>STAIP</code> 为 <code>0.0.0.0</code>。较新的固件 <code>AT+CIFSR</code> 只回 IP，MAC 要用 <code>AT+CIPSTAMAC?</code> 单独查；而 <code>AT 1.2.0.0</code> 这类老固件两者都回，用 <code>STAMAC</code> 关键字在两条应答里都能定位到 MAC。</p><h4 id="_3-2-当前热点信息-at-cwjap" tabindex="-1">3.2 当前热点信息（AT+CWJAP?） <a class="header-anchor" href="#_3-2-当前热点信息-at-cwjap" aria-label="Permalink to &quot;3.2 当前热点信息（AT+CWJAP?）&quot;">​</a></h4><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AT+CWJAP?</span></span>
<span class="line"><span>+CWJAP:&quot;MyWiFi&quot;,&quot;f4:2a:7d:f4:2b:8a&quot;,11,-56</span></span>
<span class="line"><span>OK</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>四个字段依次是热点名、BSSID、信道、信号强度（dBm）。未连接时回 <code>No AP</code>。</p><h4 id="_3-3-网关与掩码-at-cipsta" tabindex="-1">3.3 网关与掩码（AT+CIPSTA?） <a class="header-anchor" href="#_3-3-网关与掩码-at-cipsta" aria-label="Permalink to &quot;3.3 网关与掩码（AT+CIPSTA?）&quot;">​</a></h4><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AT+CIPSTA?</span></span>
<span class="line"><span>+CIPSTA:ip:&quot;192.168.10.101&quot;</span></span>
<span class="line"><span>+CIPSTA:gateway:&quot;192.168.10.1&quot;</span></span>
<span class="line"><span>+CIPSTA:netmask:&quot;255.255.255.0&quot;</span></span>
<span class="line"><span>OK</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>排查&quot;有 IP 但上不了网&quot;时先看这里：gateway 为 <code>0.0.0.0</code> 或不在本网段，出外网必然不通。</p><h4 id="_3-4-设置静态-ip-at-cwdhcp-at-cipsta" tabindex="-1">3.4 设置静态 IP（AT+CWDHCP / AT+CIPSTA） <a class="header-anchor" href="#_3-4-设置静态-ip-at-cwdhcp-at-cipsta" aria-label="Permalink to &quot;3.4 设置静态 IP（AT+CWDHCP / AT+CIPSTA）&quot;">​</a></h4><p>静态 IP 分两步：先关掉 STA 的 DHCP，再用 <code>AT+CIPSTA</code> 设地址，顺序不能反——DHCP 开着时设置的地址会被重新分配覆盖：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AT+CWDHCP=1,0</span></span>
<span class="line"><span>AT+CIPSTA=&quot;192.168.10.200&quot;,&quot;192.168.10.1&quot;,&quot;255.255.255.0&quot;</span></span>
<span class="line"><span>AT+CIPSTA?</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>三行依次是：关闭 STA 的 DHCP、设置 IP/网关/掩码、回读确认。<code>AT+CIPSTA</code> 三个参数可以只给第一个，网关与掩码默认取 <code>x.x.x.1</code> 与 <code>255.255.255.0</code>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AT+CIPSTA=&quot;192.168.10.200&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>AT+CWDHCP</code> 的参数顺序在固件版本间<strong>对调过</strong>，与 <code>AT+PING</code> 的应答差异属同一类坑：</p><table tabindex="0"><thead><tr><th>固件</th><th>参数顺序</th><th>关闭 STA DHCP</th><th>恢复 STA DHCP</th></tr></thead><tbody><tr><td>AT 1.2.0.0（老）</td><td>mode 在前</td><td><code>AT+CWDHCP=1,0</code></td><td><code>AT+CWDHCP=1,1</code></td></tr><tr><td>新固件</td><td>enable 在前</td><td><code>AT+CWDHCP=0,1</code></td><td><code>AT+CWDHCP=1,1</code></td></tr></tbody></table><p>恢复 DHCP 那一列两条指令写法恰好相同（两个参数都是 1），但语义不同；配置 STA+AP（mode/enable=2）时差异就显形了：老固件 <code>AT+CWDHCP=2,0</code> 与新固件 <code>AT+CWDHCP=0,2</code> 含义完全相反。另外 <code>AT+CWDHCP</code> 修改后需要 <code>AT+RST</code> 重启模块才生效。</p><p>三点提醒：</p><p>（1）静态 IP 必须与热点同网段，且避开 DHCP 池范围，否则与其它设备冲突。</p><p>（2）<code>AT+CIPSTA</code> 的设置保存在模块 flash，断电重启后仍是静态 IP；要恢复 DHCP 需重新执行 <code>AT+CWDHCP</code> 并重启。</p><p>（3）静态 IP 只改变本机地址的获取方式，如果设了静态 IP 后 ping 不通，先 <code>AT+CIPSTA?</code> 确认网关与掩码没配错，再回到第三节第 1 节的排查流程。</p><h3 id="_4-联通性探测-at-ping" tabindex="-1">4. 联通性探测（AT+PING） <a class="header-anchor" href="#_4-联通性探测-at-ping" aria-label="Permalink to &quot;4. 联通性探测（AT+PING）&quot;">​</a></h3><p>模块自带 ICMP 探测指令，域名与点分 IP 都行，DNS 由模块解析：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AT+PING=&quot;www.baidu.com&quot;</span></span>
<span class="line"><span>+11</span></span>
<span class="line"><span>OK</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>应答是单帧结论，<strong>不同固件格式不同</strong>（这正是第三节排查的主角）：</p><table tabindex="0"><thead><tr><th>固件</th><th>成功</th><th>失败</th></tr></thead><tbody><tr><td>新固件</td><td><code>+PING:11</code></td><td><code>+PING:TIMEOUT</code></td></tr><tr><td>AT 1.2.0.0 实测</td><td><code>+11</code></td><td>回 <code>ERROR</code>（未联网、目标不可达），未见过 <code>+TIMEOUT</code></td></tr></tbody></table><p>解析层对两种格式的四种帧都做了兼容，其中 <code>+TIMEOUT</code> 属于文档记载、该固件实测未出现，留着兜底。</p><h2 id="二、-命令封装" tabindex="-1">二、 命令封装 <a class="header-anchor" href="#二、-命令封装" aria-label="Permalink to &quot;二、 命令封装&quot;">​</a></h2><h3 id="_1-驱动层接口" tabindex="-1">1. 驱动层接口 <a class="header-anchor" href="#_1-驱动层接口" aria-label="Permalink to &quot;1. 驱动层接口&quot;">​</a></h3><p>业务层接口在 <code>Drivers/BSP/ATK_MW8266D/atk_mw8266d.h</code> 中声明，实现全部基于既有的 <code>atk_exchange()</code> 收发框架：发出指令、在窗口内等应答关键字、期间喂狗。</p><h4 id="_1-1-atk-mw8266d-set-mode" tabindex="-1">1.1 atk_mw8266d_set_mode() <a class="header-anchor" href="#_1-1-atk-mw8266d-set-mode" aria-label="Permalink to &quot;1.1 atk_mw8266d_set_mode()&quot;">​</a></h4><p>切换 WiFi 工作模式，该函数在 <code>Drivers/BSP/ATK_MW8266D/atk_mw8266d.h</code> 文件中声明：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint8_t</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> atk_mw8266d_set_mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint8_t</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>【<strong>函数作用</strong>】</p><p>发送 <code>AT+CWMODE=&lt;mode&gt;</code> 把模块切到 STA / AP / STA+AP，模式没变时模块回 <code>no change</code>，同样按成功处理。</p><p>【<strong>参数含义</strong>】</p><ul><li><code>mode</code>：目标模式，1 为 STA，2 为 AP，3 为 STA+AP</li></ul><p>【<strong>返回值</strong>】</p><ul><li><code>ATK_MW8266D_EOK</code>：已处于目标模式</li><li><code>ATK_MW8266D_ERROR</code>：模块回 ERROR 或无应答</li><li><code>ATK_MW8266D_EINVAL</code>：mode 不在 1～3</li></ul><h4 id="_1-2-atk-mw8266d-join-ap" tabindex="-1">1.2 atk_mw8266d_join_ap() <a class="header-anchor" href="#_1-2-atk-mw8266d-join-ap" aria-label="Permalink to &quot;1.2 atk_mw8266d_join_ap()&quot;">​</a></h4><p>连接热点，该函数在 <code>Drivers/BSP/ATK_MW8266D/atk_mw8266d.h</code> 文件中声明：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint8_t</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> atk_mw8266d_join_ap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> char</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ssid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> char</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">pwd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint32_t</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> timeout_ms</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>【<strong>函数作用</strong>】</p><p>发送 <code>AT+CWJAP=&quot;ssid&quot;,&quot;pwd&quot;</code> 并等待连接结论，<code>pwd</code> 为 NULL 或空串表示开放热点。</p><p>【<strong>参数含义</strong>】</p><ul><li><code>ssid</code>：热点名称，不能为空</li><li><code>pwd</code>：密码，NULL 或空串表示开放热点</li><li><code>timeout_ms</code>：最长等待时间，官方建议 15000</li></ul><p>【<strong>返回值</strong>】</p><ul><li><code>ATK_MW8266D_EOK</code>：收到 OK，连接成功</li><li><code>ATK_MW8266D_ERROR</code>：模块明确回了 FAIL/ERROR（密码错、找不到热点），立即返回</li><li><code>ATK_MW8266D_ETIMEOUT</code>：等满超时没有任何结论</li><li><code>ATK_MW8266D_EINVAL</code>：ssid 为空</li></ul><p>注意该函数<strong>没有走</strong> <code>atk_exchange()</code>：它只能等一个关键字，而 <code>AT+CWJAP</code> 失败时回的是 <code>+CWJAP:3\\r\\nFAIL</code>、没有 OK，用它会白等满超时，把&quot;密码错&quot;误报成&quot;超时&quot;。这里自己收帧，同时认 OK 与 FAIL/ERROR，密码错 1 s 内就出结论。</p><h4 id="_1-3-atk-mw8266d-get-mac" tabindex="-1">1.3 atk_mw8266d_get_mac() <a class="header-anchor" href="#_1-3-atk-mw8266d-get-mac" aria-label="Permalink to &quot;1.3 atk_mw8266d_get_mac()&quot;">​</a></h4><p>查询本机 MAC，该函数在 <code>Drivers/BSP/ATK_MW8266D/atk_mw8266d.h</code> 文件中声明：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint8_t</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> atk_mw8266d_get_mac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">char</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">buf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint16_t</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>【<strong>函数作用</strong>】</p><p>优先发 <code>AT+CIPSTAMAC?</code> 查 MAC；指令不被认时退回 <code>AT+CIFSR</code> 的 <code>STAMAC</code> 字段（老固件把 IP 与 MAC 一起回），两条应答里 MAC 都在 <code>STAMAC</code> 之后的第一对引号内。</p><p>【<strong>参数含义</strong>】</p><ul><li><code>buf</code>：存放 <code>xx:xx:xx:xx:xx:xx</code> 的缓冲区</li><li><code>size</code>：缓冲区字节数，至少 18</li></ul><p>【<strong>返回值</strong>】</p><ul><li><code>ATK_MW8266D_EOK</code>：成功，<code>buf</code> 内为 MAC 字符串</li><li><code>ATK_MW8266D_ERROR</code>：两条指令都失败或应答里找不到 MAC</li><li><code>ATK_MW8266D_EINVAL</code>：缓冲区为空或太小</li></ul><h4 id="_1-4-atk-mw8266d-get-ap-info" tabindex="-1">1.4 atk_mw8266d_get_ap_info() <a class="header-anchor" href="#_1-4-atk-mw8266d-get-ap-info" aria-label="Permalink to &quot;1.4 atk_mw8266d_get_ap_info()&quot;">​</a></h4><p>查询当前所连热点，该函数在 <code>Drivers/BSP/ATK_MW8266D/atk_mw8266d.h</code> 文件中声明：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint8_t</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> atk_mw8266d_get_ap_info</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">char</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ssid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint16_t</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> ssid_size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">                                char</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">bssid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint16_t</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> bssid_size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">                                int16_t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">channel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int16_t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">rssi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>【<strong>函数作用</strong>】</p><p>发送 <code>AT+CWJAP?</code> 并解析 <code>+CWJAP:&quot;ssid&quot;,&quot;bssid&quot;,channel,rssi</code>，各输出参数均可为 NULL 按需取用。</p><p>【<strong>参数含义</strong>】</p><ul><li><code>ssid</code> / <code>ssid_size</code>：热点名称落点，建议 33 字节</li><li><code>bssid</code> / <code>bssid_size</code>：热点 MAC 落点，建议 18 字节</li><li><code>channel</code>：信道落点</li><li><code>rssi</code>：信号强度落点（dBm）</li></ul><p>【<strong>返回值</strong>】</p><ul><li><code>ATK_MW8266D_EOK</code>：已连上热点</li><li><code>ATK_MW8266D_ERROR</code>：未连接（回答 <code>No AP</code>）或应答解析失败</li></ul><h4 id="_1-5-atk-mw8266d-leave-ap" tabindex="-1">1.5 atk_mw8266d_leave_ap() <a class="header-anchor" href="#_1-5-atk-mw8266d-leave-ap" aria-label="Permalink to &quot;1.5 atk_mw8266d_leave_ap()&quot;">​</a></h4><p>断开热点，该函数在 <code>Drivers/BSP/ATK_MW8266D/atk_mw8266d.h</code> 文件中声明：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint8_t</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> atk_mw8266d_leave_ap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>【<strong>函数作用</strong>】</p><p>发送 <code>AT+CWQAP</code> 断开当前热点。断开只是脱网，STA 模式不变，之后 IP 回落 <code>0.0.0.0</code>，再查 <code>AT+CWJAP?</code> 会回 <code>No AP</code>。</p><p>【<strong>参数含义</strong>】</p><p>无参数。</p><p>【<strong>返回值</strong>】</p><ul><li><code>ATK_MW8266D_EOK</code>：已断开</li><li><code>ATK_MW8266D_ERROR</code>：模块回 ERROR 或无应答</li></ul><h4 id="_1-6-atk-mw8266d-ping-host" tabindex="-1">1.6 atk_mw8266d_ping_host() <a class="header-anchor" href="#_1-6-atk-mw8266d-ping-host" aria-label="Permalink to &quot;1.6 atk_mw8266d_ping_host()&quot;">​</a></h4><p>主机探测，该函数在 <code>Drivers/BSP/ATK_MW8266D/atk_mw8266d.h</code> 文件中声明：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint8_t</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> atk_mw8266d_ping_host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> char</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint16_t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">time_ms</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>【<strong>函数作用</strong>】</p><p>发送 <code>AT+PING=&quot;host&quot;</code> 做一次 ICMP 探测，域名与点分 IP 都可以，DNS 由模块解析，一次探测最长等 6 s（模块自身约 5 s 超时）。</p><p>【<strong>参数含义</strong>】</p><ul><li><code>host</code>：域名或点分 IP，如 <code>www.baidu.com</code>、<code>192.168.10.103</code></li><li><code>time_ms</code>：往返时间落点（ms），可为 NULL</li></ul><p>【<strong>返回值</strong>】</p><ul><li><code>ATK_MW8266D_EOK</code>：收到应答，<code>time_ms</code> 带回往返时间</li><li><code>ATK_MW8266D_ERROR</code>：模块回 <code>+PING:TIMEOUT</code>，探测确实不通</li><li><code>ATK_MW8266D_ECMD</code>：模块回 ERROR，指令不存在或不接受</li><li><code>ATK_MW8266D_ETIMEOUT</code>：等满超时没有任何结论</li><li><code>ATK_MW8266D_EINVAL</code>：host 为空</li></ul><p>应答解析同时兼容新老两种格式（<code>+PING:11</code> 与 <code>+11</code>），并要求收齐结论或 OK 就立即返回，不干等满超时，实现见第三节。</p><h3 id="_2-控制台命令" tabindex="-1">2. 控制台命令 <a class="header-anchor" href="#_2-控制台命令" aria-label="Permalink to &quot;2. 控制台命令&quot;">​</a></h3><p>命令处理在 <code>Drivers/BSP/ATK_MW8266D/atk_mw8266d_test.c</code> 中实现，入口为 <code>atk_mw8266d_wifi_cmd()</code>，统一注册在 <code>wifi</code> 命令名下，按第一个参数分子命令。</p><h4 id="_2-1-wifi-info" tabindex="-1">2.1 wifi info <a class="header-anchor" href="#_2-1-wifi-info" aria-label="Permalink to &quot;2.1 wifi info&quot;">​</a></h4><p>打印当前网络信息：模式、热点名、BSSID、信道、信号强度、IP、MAC：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>APP: echo: wifi info</span></span>
<span class="line"><span>[ESP8266] mode  = 1 (STA)</span></span>
<span class="line"><span>[ESP8266] ssid  = MyWiFi</span></span>
<span class="line"><span>[ESP8266] bssid = f4:2a:7d:f4:2b:8a, ch = 11, rssi = -56 dBm</span></span>
<span class="line"><span>[ESP8266] ip    = 192.168.10.101</span></span>
<span class="line"><span>[ESP8266] mac   = dc:4f:22:xx:xx:be</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>未联网时热点项显示 <code>(not joined)</code>、IP 为 <code>0.0.0.0</code> 并附说明，&quot;查询失败&quot;与&quot;没连上&quot;分开打印。</p><h4 id="_2-2-wifi-join" tabindex="-1">2.2 wifi join <a class="header-anchor" href="#_2-2-wifi-join" aria-label="Permalink to &quot;2.2 wifi join&quot;">​</a></h4><p>先 ping 模块确认在线，再按需切 STA，然后连接；成功后自动打印网络信息：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>APP: echo: wifi join MyWiFi 12345678</span></span>
<span class="line"><span>[ESP8266] ---- wifi join ----</span></span>
<span class="line"><span>[ESP8266] mode  = 1 (STA)</span></span>
<span class="line"><span>[ESP8266] joining &quot;MyWiFi&quot; ...</span></span>
<span class="line"><span>[ESP8266] joined</span></span>
<span class="line"><span>[ESP8266] mode  = 1 (STA)</span></span>
<span class="line"><span>[ESP8266] ssid  = MyWiFi</span></span>
<span class="line"><span>[ESP8266] ip    = 192.168.10.101</span></span>
<span class="line"><span>[ESP8266] mac   = dc:4f:22:xx:xx:be</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>三种用法：</p><p>（1）<code>wifi join &lt;ssid&gt; [pwd]</code>：用给定热点连接，不给密码按开放热点处理。</p><p>（2）<code>wifi join</code>：使用 <code>atk_mw8266d.h</code> 中的默认热点宏（<code>ATK_MW8266D_WIFI_SSID</code> / <code>ATK_MW8266D_WIFI_PWD</code>，仓库里是占位符，真实凭据不写入代码）。</p><p>（3）<code>wifi join</code> 参数按空格切分，热点名与密码里不能带空格。</p><h4 id="_2-3-wifi-leave" tabindex="-1">2.3 wifi leave <a class="header-anchor" href="#_2-3-wifi-leave" aria-label="Permalink to &quot;2.3 wifi leave&quot;">​</a></h4><p>断开热点并打印断开后的网络状态：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>APP: echo: wifi leave</span></span>
<span class="line"><span>[ESP8266] ---- wifi leave ----</span></span>
<span class="line"><span>[ESP8266] left the AP</span></span>
<span class="line"><span>[ESP8266] ssid  = (not joined)</span></span>
<span class="line"><span>[ESP8266] ip    = 0.0.0.0 (not joined to an AP)</span></span>
<span class="line"><span>[ESP8266] mac   = dc:4f:22:xx:xx:be</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h4 id="_2-4-wifi-ping" tabindex="-1">2.4 wifi ping <a class="header-anchor" href="#_2-4-wifi-ping" aria-label="Permalink to &quot;2.4 wifi ping&quot;">​</a></h4><p>经模块探测主机连通性，支持连续探测并统计成功率：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>APP: echo: wifi ping www.baidu.com 3</span></span>
<span class="line"><span>[ESP8266] ping www.baidu.com x3</span></span>
<span class="line"><span>[ESP8266] reply from www.baidu.com: time=11 ms</span></span>
<span class="line"><span>[ESP8266] reply from www.baidu.com: time=13 ms</span></span>
<span class="line"><span>[ESP8266] reply from www.baidu.com: time=12 ms</span></span>
<span class="line"><span>[ESP8266] 3/3 replies</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><code>cnt</code> 取 1～10，缺省 1。三种失败分别打印：<code>TIMEOUT</code>（模块说探测不通）、<code>module ERROR</code>（指令不支持）、<code>module silent</code>（6 s 无任何应答，提示检查联网）。</p><p>两点实测观察：</p><p>（1）ping 局域网 PC 的<strong>首个</strong>探测往往要 200 ms 上下（ARP 解析，加上防火墙首次处理入站 ICMP），后续稳定在 4～6 ms，属正常现象，不是链路抖动。</p><p>（2）断开热点后再探测，模块对 <code>AT+PING</code> 直接回 <code>ERROR</code>，命令层据此打印 <code>module ERROR</code>——&quot;未联网&quot;不需要等超时就能判定。</p><h3 id="_3-注册与初始化" tabindex="-1">3. 注册与初始化 <a class="header-anchor" href="#_3-注册与初始化" aria-label="Permalink to &quot;3. 注册与初始化&quot;">​</a></h3><p><code>wifi</code> 原来注册为无参命令（只跑模块自测），联网功能加入后改为带参注册，<code>main.c</code> 中：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// flash-app/Core/Src/main.c</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">usart1_cmd_register_arg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;wifi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, atk_mw8266d_wifi_cmd);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  /* &#39;wifi [info|join ...]&#39;: 查询/联网 */</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>同一条命令名不能再用 <code>usart1_cmd_register()</code> 注册一次；命令必须在 <code>usart1_rx_start()</code> 之前注册，否则命令表已开始使用。<code>wifi join</code> 过程最长等 15 s，期间驱动层在收帧循环里喂狗，IWDG 使能后也不会复位。</p><h2 id="三、-常见问题" tabindex="-1">三、 常见问题 <a class="header-anchor" href="#三、-常见问题" aria-label="Permalink to &quot;三、 常见问题&quot;">​</a></h2><h3 id="_1-ping-不通排查实录" tabindex="-1">1. ping 不通排查实录 <a class="header-anchor" href="#_1-ping-不通排查实录" aria-label="Permalink to &quot;1. ping 不通排查实录&quot;">​</a></h3><h4 id="_1-1-现象" tabindex="-1">1.1 现象 <a class="header-anchor" href="#_1-1-现象" aria-label="Permalink to &quot;1.1 现象&quot;">​</a></h4><p>模块联网状态完全正常（<code>wifi info</code> 能看到 IP、RSSI -56 dBm），但 <code>wifi ping</code> 无论是局域网 PC 还是 <code>www.baidu.com</code>，全部打印 <code>TIMEOUT</code>。</p><h4 id="_1-2-排查步骤" tabindex="-1">1.2 排查步骤 <a class="header-anchor" href="#_1-2-排查步骤" aria-label="Permalink to &quot;1.2 排查步骤&quot;">​</a></h4><p>（1）<strong>先区分两种失败</strong>。初版解析把&quot;模块回 ERROR 帧&quot;与&quot;探测超时&quot;都显示成 <code>TIMEOUT</code>，无法判断是指令不支持还是网络不通。为此错误码里增加 <code>ATK_MW8266D_ECMD</code>，专门表示&quot;模块回 ERROR&quot;：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// flash-app/Drivers/BSP/ATK_MW8266D/atk_mw8266d.h</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ATK_MW8266D_ECMD</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">            4</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">U</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      /* 模块回 ERROR: 指令不存在或不接受 */</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>（2）<strong>用 <code>at</code> 透传命令直接问模块</strong>，绕开封装层看原始应答。这是定位的关键一步：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>APP: echo: at AT+PING=&quot;192.168.10.1&quot;</span></span>
<span class="line"><span>[ESP8266] &gt; AT+PING=&quot;192.168.10.1&quot;</span></span>
<span class="line"><span>[ESP8266]   +5</span></span>
<span class="line"><span>[ESP8266]   OK</span></span>
<span class="line"><span>APP: echo: at AT+PING=&quot;www.baidu.com&quot;</span></span>
<span class="line"><span>[ESP8266]   +11</span></span>
<span class="line"><span>[ESP8266]   OK</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>（3）<strong>对照透传结果与封装层结果</strong>：透传全部成功（网关 5 ms、公网 13 ms、域名 11 ms），封装层却全部超时——问题锁定在应答解析，而不是网络。</p><h4 id="_1-3-根因-老固件应答格式差异" tabindex="-1">1.3 根因：老固件应答格式差异 <a class="header-anchor" href="#_1-3-根因-老固件应答格式差异" aria-label="Permalink to &quot;1.3 根因：老固件应答格式差异&quot;">​</a></h4><p>模块固件是 <code>AT version:1.2.0.0</code>（Ai-Thinker，2016 年），它的 <code>AT+PING</code> 应答是 <code>+&lt;毫秒&gt;</code>（如 <code>+5</code>），超时回 <code>+TIMEOUT</code>；而解析代码按较新固件的文档实现，在等 <code>+PING:</code> 前缀。于是 <code>+5</code>、<code>+13</code> 这些结论帧被当成无关帧丢弃，等满超时报 <code>TIMEOUT</code>。</p><p>修复后 <code>wifi ping</code> 与透传结果一致（域名 11～18 ms、局域网 4～6 ms、断开后正确回 <code>module ERROR</code>）。这次排查的两个通用经验：</p><p>（1）<strong>封装层失败先透传验证</strong>。一条 <code>at AT+PING=&quot;...&quot;</code> 就把&quot;网络不通&quot;与&quot;解析错误&quot;两个假设分开，比对着代码猜快得多。</p><p>（2）<strong>老固件的应答格式不能只看新文档</strong>。Ai-Thinker 2016 年版固件在网上存量极大，解析层对新老格式做兼容是必要的成本。</p><h3 id="_2-其它典型问题" tabindex="-1">2. 其它典型问题 <a class="header-anchor" href="#_2-其它典型问题" aria-label="Permalink to &quot;2. 其它典型问题&quot;">​</a></h3><h4 id="_2-1-模块对-at-指令回-error" tabindex="-1">2.1 模块对 AT 指令回 ERROR <a class="header-anchor" href="#_2-1-模块对-at-指令回-error" aria-label="Permalink to &quot;2.1 模块对 AT 指令回 ERROR&quot;">​</a></h4><p>如果透传 <code>AT+PING=&quot;...&quot;</code> 模块直接回 <code>ERROR</code>，说明这版固件根本没有该指令（老固件指令集不全很常见）。两个选择：升级 ESP8266 AT 固件，或者改用 TCP 连接（<code>AT+CIPSTART</code>）做连通性探测。封装层此时会把这类失败单独报为 <code>module ERROR</code>，与探测超时区分开。</p><h4 id="_2-2-局域网-pc-ping-不通-但外网域名通" tabindex="-1">2.2 局域网 PC ping 不通，但外网域名通 <a class="header-anchor" href="#_2-2-局域网-pc-ping-不通-但外网域名通" aria-label="Permalink to &quot;2.2 局域网 PC ping 不通，但外网域名通&quot;">​</a></h4><p>这是 <strong>Windows 防火墙默认拦截 ICMP 入站</strong>，与模块无关。管理员 PowerShell 放行后即可：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">New-NetFirewallRule</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DisplayName </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Allow ICMPv4-In&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Protocol ICMPv4 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">IcmpType </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Direction Inbound </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Action Allow</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>实测同一局域网内，防火墙放行后模块 ping PC 正常（首个探测 200 ms 上下，后续 4～6 ms）；反过来 <strong>PC ping 模块也能通</strong>（实测 3/3 收到），但延迟高达 89～110 ms——ESP8266 处理入站 ICMP 优先级低，这个延迟是模块协议栈的开销，不能拿它衡量无线链路质量。</p><h4 id="_2-3-外网域名与局域网-ip-都探测不通" tabindex="-1">2.3 外网域名与局域网 IP 都探测不通 <a class="header-anchor" href="#_2-3-外网域名与局域网-ip-都探测不通" aria-label="Permalink to &quot;2.3 外网域名与局域网 IP 都探测不通&quot;">​</a></h4><p><code>wifi info</code> 有 IP 但 <code>wifi ping</code> 全部 <code>+PING:TIMEOUT</code> 时，按三步收敛：</p><p>（1）<code>AT+CIPSTA?</code> 看 gateway 是否为 <code>0.0.0.0</code> 或不在本网段——DHCP 没下发网关，出外网必然不通。</p><p>（2）<code>AT+PING=&quot;&lt;网关&gt;&quot;</code> ——网关是局域网里最应该通的一跳。网关都不通而网关配置正常，基本就是路由器开了 <strong>AP 客户端隔离</strong>（无线终端之间及与有线不互通），关掉即可，它同时解释 ping PC 不通。</p><p>（3）网关通再 <code>AT+PING=&quot;223.5.5.5&quot;</code> ——公网 IP 通而域名不通，是 DNS 没下发，TCP 直连 IP 不受影响。</p><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>`,161)])])}const k=a(t,[["render",p]]);export{u as __pageData,k as default};
